  String infer(String n){String x=n.toLowerCase(); if(x.contains("text")||x.contains("word")||x.contains("sentence")||x.contains("morse")||x.contains("markdown")||x.contains("slug")||x.contains("character")||x.contains("emoji")||x.contains("symbol")||x.contains("hashtag")||x.contains("bio")||x.contains("typing")||x.contains("unicode")||x.contains("ascii")||x.contains("html")||x.contains("xml")||x.contains("regex"))return "Text";if(x.contains("color")||x.contains("rgb")||x.contains("hex")||x.contains("gradient")||x.contains("contrast"))return "Color";if(x.contains("password")||x.contains("pin")||x.contains("secure")||x.contains("privacy")||x.contains("cipher")||x.contains("hash")||x.contains("checksum"))return "Security";if(x.contains("date")||x.contains("time")||x.contains("clock")||x.contains("countdown")||x.contains("timer")||x.contains("calendar")||x.contains("pomodoro")||x.contains("stopwatch"))return "Productivity";if(x.contains("file")||x.contains("pdf")||x.contains("image")||x.contains("audio")||x.contains("video")||x.contains("path")||x.contains("filename"))return "Files";if(x.contains("url")||x.contains("ip ")||x.contains("network")||x.contains("email")||x.contains("phone")||x.contains("mac address"))return "Internet";if(x.contains("converter")||x.contains("calculator")||x.contains("number")||x.contains("factorial")||x.contains("prime")||x.contains("fibonacci")||x.contains("gcd")||x.contains("lcm")||x.contains("loan")||x.contains("interest")||x.contains("discount")||x.contains("tax")||x.contains("cost")||x.contains("grade")||x.contains("gpa")||x.contains("ratio")||x.contains("density")||x.contains("rate")||x.contains("intake")||x.contains("area")||x.contains("volume")||x.contains("speed")||x.contains("weight")||x.contains("length")||x.contains("energy")||x.contains("power")||x.contains("pressure")||x.contains("angle"))return "Calculator";return "Productivity";}
