  void renderCards(LinearLayout target,String query){target.removeAllViews();List<Tool> list=new ArrayList<>();for(Tool t:tools)if((category.equals("All")||t.cat.equals(category))&&(t.name+" "+t.desc+" "+t.cat).toLowerCase().contains(query.toLowerCase()))list.add(t);for(int i=0;i<list.size();i+=2){LinearLayout r=row();for(int j=i;j<Math.min(i+2,list.size());j++){Tool t=list.get(j);LinearLayout card=column();card.setPadding(12,12,10,12);card.setBackground(shape(PANEL,LINE,18));TextView icon=text(t.icon,22,GOLD,true);card.addView(icon);card.addView(text(t.name,14,WHITE,true));card.addView(text(t.cat+" • OPEN TOOL",10,MUTED,false));card.setOnClickListener(v->openTool(t.name));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,0,8,8);r.addView(card,p);}if(list.size()%2==1&&i+1>=list.size())r.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));target.addView(r);}}
