  void showSettings(){page="Settings";body.removeAllViews();setNav();header();body.addView(text("SETTINGS",20,GREEN,true));body.addView(space(12));TextView about=text("G.I TOOL • FULL NATIVE EDITION\nPOWERED BY I KO KO\n"+tools.size()+" utilities in this build\nFavorites and preferences are stored on this device.\n\nNo account required.",16,WHITE,false);about.setPadding(16,18,16,18);about.setBackground(shape(PANEL,LINE,18));body.addView(about);body.addView(space(12));button(body,"Clear favorites",()->{favorites.clear();getSharedPreferences("gi_native",0).edit().putStringSet("favorites",new HashSet<>()).apply();toast("Favorites cleared");showSettings();});button(body,"Reset app data",()->new android.app.AlertDialog.Builder(this).setTitle("Reset G.I TOOL?").setMessage("This clears saved favorites and notes.").setNegativeButton("Cancel",null).setPositiveButton("Reset",(d,w)->{favorites.clear();notes.clear();getSharedPreferences("gi_native",0).edit().clear().apply();toast("App data reset");showSettings();}).show());}
